// Builds internal/codegen_corpus/: MoonBit parsers generated by `pegmbt` for
// the grammars of the harvested upstream test corpus (code blocks translated
// to MoonBit via tools/mbt-code-blocks.js), with tests that compare every
// recorded parse against PEG.js' outcome.
//
//   moon build --target native cmd/pegmbt && node tools/gen-codegen-corpus.js
"use strict";
const fs = require("fs");
const os = require("os");
const path = require("path");
const { execFileSync } = require("child_process");
const peg = require("./pegjs");
const { compileInternals } = require("./dump");
const { mbtString } = require("./gen-program");
const { blocks, initializers } = require("./mbt-code-blocks");

const root = path.join(__dirname, "..");
const pegmbt = path.join(root, "_build", "native", "debug", "build", "cmd", "pegmbt", "pegmbt.exe");
const outDir = path.join(root, "internal", "codegen_corpus");
const GRAMMARS_PER_PACKAGE = 30;
const corpus = fs.readFileSync(path.join(__dirname, "corpus.jsonl"), "utf8").trim().split("\n").map(JSON.parse);

function normalizeString(s) {
  let out = "";
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff) {
      const d = s.charCodeAt(i + 1);
      if (d >= 0xdc00 && d <= 0xdfff) { out += s[i] + s[i + 1]; i++; continue; }
      out += "<lone:" + c.toString(16) + ">";
    } else if (c >= 0xdc00 && c <= 0xdfff) out += "<lone:" + c.toString(16) + ">";
    else out += s[i];
  }
  return out;
}
function normalize(v) {
  if (typeof v === "string") return normalizeString(v);
  if (Array.isArray(v)) return v.map(normalize);
  if (v && typeof v === "object") {
    const r = {};
    for (const k of Object.keys(v)) if (v[k] !== undefined) r[normalizeString(k)] = normalize(v[k]);
    return r;
  }
  return v;
}
function errorJson(e) {
  const r = { name: e.name, message: e.message };
  if (e.location !== undefined) r.location = e.location;
  if (e.expected !== undefined) r.expected = e.expected;
  if (e.found !== undefined) r.found = e.found;
  return r;
}
const isLabel = l => /^[a-z_][A-Za-z0-9_]*$/.test(l) && l !== "_";

// Translates a grammar's code blocks to MoonBit, or explains why not.
function translate(grammar) {
  let ast;
  try { ast = peg.parser.parse(grammar); } catch (e) { return { skip: "syntax" }; }
  const labels = [];
  const codes = [];
  (function walk(n) {
    if (!n || typeof n !== "object") return;
    if (n.type === "labeled" && n.label) labels.push(n.label);
    if (typeof n.code === "string" && n.type) codes.push(n);
    for (const k in n) if (k !== "location" && k !== "_alwaysConsumesOnSuccess") walk(n[k]);
  })(ast);
  if (labels.some(l => !isLabel(l))) return { skip: "label" };
  let source = grammar;
  for (const node of codes) {
    const key = node.code.trim();
    const mbt = node.type === "initializer" ? initializers[key] : blocks[key] && blocks[key].code;
    if (mbt === undefined) return { skip: "code" };
    source = source.split("{" + node.code + "}").join("{\n" + mbt + "\n}");
  }
  // Labels referenced by translations must be in scope.
  let internals;
  try { internals = compileInternals(grammar).ast; } catch (e) { return { skip: "compile" }; }
  for (const f of internals.functions) {
    const b = blocks[f.body.trim()];
    if (b && (b.uses || []).some(l => f.params.indexOf(l) < 0)) return { skip: "scope" };
  }
  return { source };
}

// ---- collect cases ---------------------------------------------------------
const gens = corpus.filter(r => r.kind === "generate" && r.ok);
const parses = corpus.filter(r => r.kind === "parse");
const grammars = new Map(); // translated source -> { variants: Map }
const skipped = {};
for (const g of gens) {
  const o = g.options && typeof g.options === "object" && !("$" in g.options) ? g.options : {};
  if (o.plugins !== undefined || o.output !== undefined || o.context !== undefined) continue;
  const t = translate(g.grammar);
  if (t.skip) { skipped[t.skip] = (skipped[t.skip] || 0) + 1; continue; }
  if (!grammars.has(t.source)) grammars.set(t.source, { variants: new Map() });
  const variant = { start: o.allowedStartRules, cache: !!o.cache, trace: !!o.trace, size: o.optimize === "size" };
  const vkey = JSON.stringify(variant);
  const entry = grammars.get(t.source);
  if (!entry.variants.has(vkey)) entry.variants.set(vkey, Object.assign(variant, { parses: new Map() }));
  const v = entry.variants.get(vkey);
  for (const p of parses.filter(p => p.gen === g.id)) {
    const po = p.options && typeof p.options === "object" && !("$" in p.options) ? p.options : {};
    const k = JSON.stringify([p.input, po]);
    if (!v.parses.has(k)) v.parses.set(k, { input: p.input, options: po, expected: p.ok ? { ok: p.result } : { error: errorJson(p.error) } });
  }
}

// ---- emit packages -----------------------------------------------------------
fs.rmSync(outDir, { recursive: true, force: true });
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "pegmbt-"));
const helpers = fs.readFileSync(path.join(__dirname, "codegen-corpus-helpers.mbt"), "utf8");
const list = [...grammars.entries()];
let parserCount = 0;
let parseCount = 0;
for (let pk = 0; pk * GRAMMARS_PER_PACKAGE < list.length; pk++) {
  const dir = path.join(outDir, "p" + pk);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, "moon.pkg"),
    'import {\n  "bobzhang/peg/runtime",\n  "bobzhang/peg/vm",\n  "bobzhang/peg/bytecode",\n}\n' +
    'import {\n  "bobzhang/peg/internal/fixture",\n  "moonbitlang/core/json",\n} for "test"\n');
  fs.writeFileSync(path.join(dir, "helpers.mbt"), helpers);
  const test = ["// Code generated by tools/gen-codegen-corpus.js. DO NOT EDIT.", "",
    "///|", "let cases : Array[(String, Bool, (String, Map[String, @runtime.Value[Unit]], @runtime.Tracer[Unit]?) -> @runtime.Value[Unit] raise, Array[(String, String, String)])] = ["];
  list.slice(pk * GRAMMARS_PER_PACKAGE, (pk + 1) * GRAMMARS_PER_PACKAGE).forEach(([source, entry], gi) => {
    const gfile = path.join(tmp, "g.pegjs");
    fs.writeFileSync(gfile, source);
    [...entry.variants.values()].forEach((v, vi) => {
      const prefix = "g" + gi + "v" + vi + "_";
      const args = [gfile, "-o", path.join(dir, prefix + "parser.mbt"), "--name-prefix", prefix];
      if (v.start) args.push("-a", v.start.join(","));
      if (v.cache) args.push("--cache");
      if (v.trace) args.push("--trace");
      if (v.size) args.push("-O", "size");
      execFileSync(pegmbt, args);
      parserCount++;
      test.push("  (" + mbtString(prefix) + ", " + v.trace + ", (input, options, tracer) => @p" + pk + "." + prefix + "parse(input, options~, tracer?), [");
      for (const p of v.parses.values()) {
        parseCount++;
        test.push("    (" + mbtString(p.input) + ", " + mbtString(JSON.stringify(normalize(p.options))) + ", " +
          mbtString(JSON.stringify(normalize(p.expected))) + "),");
      }
      test.push("  ]),");
    });
  });
  test.push("]", "", `///|
test "generated parsers match PEG.js" {
  let mut failures = 0
  for c in cases {
    let (name, trace, parse, parses) = c
    for p in parses {
      let (input, options_text, expected_text) = p
      let options = @fixture.parse_options(options_text)
      let tracer : @runtime.Tracer[Unit]? = if trace { Some({ trace: _ => () }) } else { None }
      let actual = @fixture.outcome(() => parse(input, options, tracer))
      let expected = @json.parse(expected_text)
      if actual != expected {
        failures += 1
        if failures <= 5 {
          println("\\{name} differs on \\{input} \\{options_text}")
          println("  expected: \\{expected.stringify()}")
          println("  actual:   \\{actual.stringify()}")
        }
      }
    }
  }
  assert_eq(failures, 0)
}
`);
  fs.writeFileSync(path.join(dir, "cases_test.mbt"), test.join("\n"));
}
fs.rmSync(tmp, { recursive: true, force: true });
console.log("grammars:", grammars.size, "parsers:", parserCount, "parses:", parseCount, "skipped generate records:", skipped);
